\label{propositionplanarccooperadff}
    The functor $\mathrm{Conil}$ from dg $\overline{\mathbb{T}}_\mathrm{pl}$-coalgebras to coaugmented planar dg cooperads
    is fully faithful.

\label{definitioncomp}
Let $M, N$ be two dg $\mathbb S$-modules. We define the \textit{composition product} $M \circ N$ as the coequaliser of the reflexive pair of maps

\[
\begin{tikzcd}[column sep=5pc,row sep=4pc]
M \circ N \coloneqq \mathrm{Coeq}\Bigg(\displaystyle ((\mathrm{U}(M) \otimes \mathbb S) \circ_\mathrm{pl} (\mathrm{U}(N) \otimes \mathbb S))\otimes \mathbb S \arrow[r,"\mu_{\mathrm{U}(M) \circ_\mathrm{pl} \mathrm{U}(N)}~\varphi_{\mathrm{U}(M),\mathrm{U}(N)} \otimes \mathbb S",shift right=1.1ex,swap]  \arrow[r,"(\pi_M \circ_\mathrm{pl} \pi_N) \otimes \mathbb{S}"{name=SD},shift left=1.1ex ]
&( \mathrm{U}(M) \circ_\mathrm{pl}  \mathrm{U}(N)) \otimes \mathbb S\Bigg)~,
\end{tikzcd}
\]
\vspace{0.1pc}

in the category of dg $\mathbb S$-modules.

\label{corollary: iso de la récurrence sur les arbres}
Let $n$ be a natural integer and $M$ a dg $\mathbb{S}$-module. The composition of the free operad $\gamma_M: \mathbb{T} \circ \mathbb{T} M \longrightarrow \mathbb{T} M$ induces the following isomorphisms

    \begin{align*}
        &M \circ \mathbb{T} M \cong \overline{\mathbb{T}} M~,
        \\
        &M \circ \mathbb{T}_{\leq n} M \cong \overline{\mathbb{T}}_{\leq n+1} M~,
    \end{align*}

    of dg $\mathbb{S}$-modules.

\label{propositionplanarccooperadff}
    The functor $\mathrm{Conil}$ from dg $\overline{\mathbb{T}}$-coalgebras to coaugmented dg cooperads
    is fully faithful.

A \textit{planar tree} $t$ is a tuple $(\mathrm{edges}(t), \mathrm{leaves}(t), <, \tilde <)$ where
    \begin{itemize}
        \item $(\mathrm{edges}(t), <)$ is a finite non-empty poset called the poset of edges of $t$. It has a least element called the root. Moreover, for every edge $e$, the subposet spanned by elements that are lower that $e$ $\{e' \in \mathrm{edges}(t)|\ e' \leq e\}$ is a linear poset;
        \item $\mathrm{leaves}(t)$ is a subset of the set of maximal elements of the set of edges;
        \item $\tilde <$ is an additional order on the set of edges, called the planar order, that is linear and so that 
        \begin{itemize}
            \item for every two edges $e,e'$, $e ~ \tilde < ~ e'$ whenever $e < e'$;
            \item for every three edges $e,e',e''$ so that $e < e'$ and $e'' \tilde < e'$, then $e$ and $e''$ are comparable for the order $<$ in the sense that either $e'' < e$ or $e'' = e$ or  $e'' > e$.
        \end{itemize}
    \end{itemize}

Let $t$ be a planar tree. A \textit{subtree} $t'$ of $t$ is the data of a tuple
    $(\mathrm{edges}(t'), \mathrm{leaves}(t'), <, \tilde <)$ where
    \begin{itemize}
        \item $\mathrm{edges}(t')$ is a subset of $\mathrm{edges}(t)$ and $<, \tilde <$ are the orders induced from those of $t$;
        \item $\mathrm{leaves}(t)$ is a subset of the set of maximal elements of the poset of edges of $(t', <)$;
        \item this two subsets satisfy the following conditions
        \begin{itemize}
            \item the poset $(\mathrm{edges}(t'), <)$ has a least element (the root of $t'$);
            \item for every three edges $e < e' < e''$ of $t$, $e'$ belongs to $t'$ whenever $e$ and $e''$ do;
            \item for every node $n$ of $t$ that belongs to $t'$, either the underlying edge of $n$ is a leaf of $t'$ or $t'$ has in its edges all the inputs of $n$;
            \item a leaf of $t$ that belongs to the edges of $t'$ is actually a leaf of $t'$ that is, $\mathrm{leaves}(t) \cap \mathrm{edges}(t') \subset \mathrm{leaves}(t)$.
        \end{itemize}
        In particular, $t'$ is a planar tree.
    \end{itemize}

Let $t$ be a non-trivial planar tree. A \textit{partition of} $t$ into non trivial subtrees is the data of a natural integer $m \geq 1$ together with non trivial subtrees $t_1, \ldots, t_m$ so that
    \begin{itemize}
        \item for every node $n$ of $t$, there exists a unique $i$ so that $n$ is a node of $t_i$;
        \item for every leaf $l$ of $t$, there exists a unique $i$ so that $l$ is an edge (and thus a leaf) of $t_i$.
    \end{itemize}

Let $t$ be a non-trivial planar tree and let $t_1, \ldots, t_m$ be a partition of $t$. Then
    \begin{itemize}
        \item every node edge $e$ of $t$ belongs to at least one and at  most two of these subtrees;
        \item the root of $t$ belongs to only one subtree;
        \item the root of a subtree is a node of this subtree and thus a node of $t$ 
        \item an node edge of $t$ can be the root of only one subtree. 
    \end{itemize}

Let $t$ be a non-trivial planar subtree with $k$ nodes $t_1, \ldots, t_k$ be non-trivial trees so that the number of leaves of $t_i$ is equal to the number of inputs of the $ith$ node. This gives a canonical isomorphism
    $$
    \mathrm{edges}(t) \backslash \{\mathrm{root}(t)\} \cong  \coprod_{i=1}^k \mathrm{leaves}(t_i).
    $$
    Then we define the \textit{grafting tree}
    $\mathrm{graft}_t(t_1, \ldots, t_k)$ of the trees $t_1, \ldots, t_k$
    along $t$ as the planar tree so that
    \begin{itemize}
        \item the set of node edges is $\coprod_{i=1}^k \mathrm{nodes}(t_i)$;
        \item the set of leaves is the subset of $\coprod_{i=1}^k \mathrm{leaves}(t_i)$ made up of elements whose image in $\mathrm{edges}(t)$ is a leaf of $t$;
        \item for every two edges $e,e'$ of $\mathrm{graft}_t(t_1, \ldots, t_k)$ that proceeds from the two trees $t_i,t_j$ attached to the nodes $n_i, n_j$ of $t$, $e<e'$ 
        if and only if either
        \begin{itemize}
            \item $n_i < n_j$ and $e < l$ where $l$ is the leaf of $t_i$ that corresponds to the unique input $x$ of the node $n_i$ of $t$ so that $x \leq n_j$;
            \item $i=j$ and $e < e'$ within $t_i$;
        \end{itemize}
        \item for every two edges $e,e'$ of $\mathrm{graft}_t(t_1, \ldots, t_k)$ that proceeds from the two trees $t_i,t_j$ attached to the nodes $n_i, n_j$ of $t$, $e<e'$ 
        if and only if either
        \begin{itemize}
            \item $n_i ~ \tilde < ~ n_j$ and $n_i$ and $n_j$ are not comparable for $<$;
            \item $n_i < n_j$ and $e ~ \tilde < ~ l$ where $l$ is the leaf of $t_i$ that corresponds to the unique input $x$ of the node $n_i$ of $t$ so that $x \leq n_j$;
            \item $i=j$ and $e~ \tilde < ~e'$ within $t_i$.
        \end{itemize}
    \end{itemize}
